export default "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Tailgate</title>\n<style>\n:root{--bg:#0b0e14;--panel:#121722;--panel2:#171d2b;--line:#222a3b;--text:#e6eaf2;--dim:#8b95a9;--teal:#00dcbe;--violet:#965aff;--green:#3ddc84;--yellow:#ffc857;--red:#ff6b6b;--grad:linear-gradient(90deg,#00dcbe,#965aff)}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 system-ui,Segoe UI,Roboto,sans-serif}\nheader{display:flex;align-items:center;gap:16px;padding:16px 28px;border-bottom:1px solid var(--line);position:sticky;top:0;background:rgba(11,14,20,.92);backdrop-filter:blur(8px);z-index:5;flex-wrap:wrap}\n.logo{font-weight:800;font-size:22px;letter-spacing:.5px;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}\n.ver{color:var(--dim);font-size:12px}\n.spacer{flex:1}\n.pill{padding:5px 12px;border-radius:999px;background:var(--panel2);border:1px solid var(--line);font-size:12px;color:var(--dim)}\n.pill b{color:var(--text)}\nmain{max-width:1180px;margin:0 auto;padding:22px 28px 60px}\nnav{display:flex;gap:6px;margin-bottom:18px}\nnav button{background:none;border:0;color:var(--dim);padding:9px 16px;border-radius:9px;cursor:pointer;font-size:14px;font-weight:600}\nnav button.on{background:var(--panel2);color:var(--text);box-shadow:inset 0 -2px 0 var(--teal)}\n.bar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px;align-items:center}\ninput[type=search]{flex:1;min-width:220px;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:10px 14px;color:var(--text);font-size:14px;outline:none}\ninput[type=search]:focus{border-color:var(--teal)}\n.chip{padding:7px 13px;border-radius:999px;background:var(--panel);border:1px solid var(--line);color:var(--dim);cursor:pointer;font-size:13px}\n.chip.on{border-color:var(--teal);color:var(--teal)}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:14px}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:16px;display:flex;flex-direction:column;gap:10px;transition:border-color .15s,transform .15s}\n.card:hover{border-color:#34405a;transform:translateY(-1px)}\n.row1{display:flex;align-items:center;gap:8px}\n.name{font-weight:700;font-size:15px;color:var(--text);text-decoration:none;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.name:hover{color:var(--teal)}\n.tier{font-size:11px;font-weight:800;padding:2px 8px;border-radius:6px}\n.tier.S{background:rgba(150,90,255,.18);color:#b794ff}.tier.A{background:rgba(61,220,132,.15);color:var(--green)}.tier.B{background:rgba(255,200,87,.15);color:var(--yellow)}\n.desc{color:var(--dim);font-size:13px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;min-height:58px}\n.meta{display:flex;gap:12px;align-items:center;color:var(--dim);font-size:12px;flex-wrap:wrap}\n.score{display:flex;align-items:center;gap:7px}\n.track{width:70px;height:6px;background:var(--line);border-radius:3px;overflow:hidden}\n.fill{height:100%;background:var(--grad)}\n.tags{display:flex;gap:6px;flex-wrap:wrap}\n.tag{font-size:11px;padding:2px 8px;border-radius:6px;background:var(--panel2);color:var(--dim)}\n.tag.good{color:var(--green)}.tag.cur{color:#b794ff}\n.foot{display:flex;gap:8px;margin-top:auto}\nbutton.btn{border:0;border-radius:9px;padding:8px 16px;font-weight:700;cursor:pointer;font-size:13px;color:#06201b;background:var(--grad)}\nbutton.btn:hover{filter:brightness(1.1)}\nbutton.btn:disabled{opacity:.5;cursor:wait}\nbutton.ghost{background:var(--panel2);color:var(--text);border:1px solid var(--line)}\nbutton.danger{background:rgba(255,107,107,.12);color:var(--red);border:1px solid rgba(255,107,107,.3)}\n.ok{color:var(--green);font-weight:700;padding:8px 4px}\n.list{display:flex;flex-direction:column;gap:8px}\n.irow{display:grid;grid-template-columns:54px 1fr 150px 200px;gap:14px;align-items:center;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:12px 16px}\n.irow .t{font-weight:700}.irow .s{color:var(--dim);font-size:12px}\n.sw{width:44px;height:24px;border-radius:12px;background:var(--line);position:relative;cursor:pointer;border:0}\n.sw::after{content:\"\";position:absolute;top:3px;left:3px;width:18px;height:18px;border-radius:50%;background:#fff;transition:left .15s}\n.sw.on{background:var(--teal)}.sw.on::after{left:23px}\n.cost{font-variant-numeric:tabular-nums;font-size:13px}\n.cost .track{width:100%;margin-top:4px}\n.warn{background:rgba(255,200,87,.1);border:1px solid rgba(255,200,87,.35);color:var(--yellow);padding:11px 16px;border-radius:11px;margin-bottom:12px;font-size:13px}\n.upd{background:rgba(0,220,190,.1);border:1px solid rgba(0,220,190,.35);color:var(--teal);padding:11px 16px;border-radius:11px;margin-bottom:12px;display:flex;align-items:center;gap:12px}\n.pcard{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px;display:flex;flex-direction:column;gap:10px}\n.pcard h3{margin:0;font-size:17px}\n.modal{position:fixed;inset:0;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;z-index:20}\n.box{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:24px;width:min(560px,92vw);max-height:80vh;overflow:auto}\n.step{padding:7px 0;border-bottom:1px solid var(--line);font-size:13px;display:flex;gap:10px}\n.step b{width:70px}.step .a-install{color:var(--green)}.step .a-enable{color:var(--teal)}.step .a-disable{color:var(--yellow)}\n#toast{position:fixed;bottom:22px;right:22px;display:flex;flex-direction:column;gap:8px;z-index:30}\n.t{background:var(--panel2);border:1px solid var(--line);padding:11px 16px;border-radius:10px;max-width:420px;font-size:13px}\n.t.err{border-color:var(--red);color:var(--red)}.t.good{border-color:var(--green)}\n.empty{color:var(--dim);padding:40px;text-align:center}\n@media(max-width:760px){.irow{grid-template-columns:54px 1fr}.irow>:nth-child(n+3){grid-column:1/-1}}\n</style>\n</head>\n<body>\n<header>\n  <span class=\"logo\">tailgate</span><span class=\"ver\" id=\"ver\"></span>\n  <span class=\"spacer\"></span>\n  <span class=\"pill\">Always-on: <b id=\"tot\">...</b> tokens/session</span>\n  <button class=\"btn ghost\" id=\"refresh\">Refresh catalog</button>\n</header>\n<main>\n  <div id=\"banners\"></div>\n  <nav id=\"tabs\">\n    <button data-t=\"discover\" class=\"on\">Discover</button>\n    <button data-t=\"installed\">Installed</button>\n    <button data-t=\"profiles\">Profiles</button>\n  </nav>\n  <section id=\"discover\">\n    <div class=\"bar\">\n      <input type=\"search\" id=\"q\" placeholder=\"Search name or description\">\n      <span class=\"chip on\" data-f=\"all\">All</span>\n      <span class=\"chip\" data-f=\"savers\">Token savers</span>\n      <span class=\"chip\" data-f=\"new\">Not installed</span>\n    </div>\n    <div class=\"grid\" id=\"grid\"></div>\n  </section>\n  <section id=\"installed\" hidden></section>\n  <section id=\"profiles\" hidden></section>\n</main>\n<div id=\"toast\"></div>\n<script>\n(function(){\nvar TOKEN = new URLSearchParams(location.search).get('t') || '';\nvar S = {tab:'discover', filter:'all', q:'', data:null};\nvar $ = function(s){return document.querySelector(s)};\nfunction el(tag, props, kids){\n  var e = document.createElement(tag);\n  for (var k in (props||{})) {\n    if (k === 'text') e.textContent = props[k];\n    else if (k === 'class') e.className = props[k];\n    else if (k.slice(0,2) === 'on') e.addEventListener(k.slice(2), props[k]);\n    else e.setAttribute(k, props[k]);\n  }\n  (kids||[]).forEach(function(c){ if (c) e.appendChild(typeof c === 'string' ? document.createTextNode(c) : c); });\n  return e;\n}\nfunction api(path, body){\n  return fetch('/api/'+path, {\n    method: body ? 'POST' : 'GET',\n    headers: {'x-tg-token': TOKEN, 'content-type':'application/json'},\n    body: body ? JSON.stringify(body) : undefined\n  }).then(function(r){ return r.json().then(function(j){ if(!r.ok) throw new Error(j.error||r.statusText); return j; }); });\n}\nfunction toast(msg, kind){\n  var t = el('div', {class:'t '+(kind||''), text:msg});\n  $('#toast').appendChild(t);\n  setTimeout(function(){ t.remove(); }, kind==='err' ? 8000 : 4000);\n}\nfunction fmt(n){ return n == null ? 'n/a' : n.toLocaleString(); }\nfunction stars(n){ return n >= 1000 ? (n/1000).toFixed(1)+'k' : String(n); }\n\nfunction busy(btn, fn){\n  var old = btn.textContent; btn.disabled = true; btn.textContent = '...';\n  return fn().then(function(){ btn.disabled=false; btn.textContent=old; },\n                   function(e){ btn.disabled=false; btn.textContent=old; toast(e.message,'err'); });\n}\n\nfunction load(){\n  return api('state').then(function(d){ S.data = d; render(); }).catch(function(e){ toast(e.message,'err'); });\n}\n\nfunction render(){\n  var d = S.data; if(!d) return;\n  $('#ver').textContent = 'v'+d.version;\n  $('#tot').textContent = fmt(d.totalTokens);\n  var b = $('#banners'); b.textContent='';\n  if (d.update) {\n    var u = el('div',{class:'upd'},[el('span',{text:'Tailgate v'+d.update.version+' is available.'}),\n      el('button',{class:'btn',text:'Update now',onclick:function(ev){ busy(ev.target,function(){\n        return api('selfupdate',{}).then(function(){ toast('Updated. Reopen Tailgate.','good'); });}); }})]);\n    b.appendChild(u);\n  }\n  d.conflicts.forEach(function(c){ b.appendChild(el('div',{class:'warn',text:'Conflict: '+c.message})); });\n  if (S.tab==='discover') renderDiscover();\n  if (S.tab==='installed') renderInstalled();\n  if (S.tab==='profiles') renderProfiles();\n}\n\nfunction renderDiscover(){\n  var d = S.data, g = $('#grid'); g.textContent='';\n  var q = S.q.toLowerCase();\n  var items = d.catalog.filter(function(e){\n    if (S.filter==='savers' && !e.tokenSaver) return false;\n    if (S.filter==='new' && e.installed) return false;\n    return !q || (e.id+' '+e.description+' '+e.category).toLowerCase().indexOf(q) >= 0;\n  });\n  if (!items.length) { g.appendChild(el('div',{class:'empty',text:'No matches.'})); return; }\n  items.forEach(function(e){\n    var foot = el('div',{class:'foot'});\n    if (e.installed) foot.appendChild(el('span',{class:'ok',text:'✓ Installed'}));\n    else if (e.kind === 'unknown') foot.appendChild(el('a',{href:'https://github.com/'+e.id,target:'_blank',rel:'noopener'},[el('button',{class:'btn ghost',text:'Manual install (open repo)'})]));\n    else foot.appendChild(el('button',{class:'btn',text:'Install',onclick:function(ev){ busy(ev.target,function(){\n      return api('install',{id:e.id}).then(function(){ toast('Installed '+e.id+'. Restart Claude Code.','good'); return load(); }); }); }}));\n    var tags = el('div',{class:'tags'},[\n      e.curated ? el('span',{class:'tag cur',text:'curated'}) : null,\n      el('span',{class:'tag '+(e.tokenSaver?'good':''),text:e.category}),\n      el('span',{class:'tag',text:e.kind==='marketplace'?'plugin':e.kind})]);\n    g.appendChild(el('div',{class:'card'},[\n      el('div',{class:'row1'},[el('span',{class:'tier '+e.tier,text:e.tier}),\n        el('a',{class:'name',href:'https://github.com/'+e.id,target:'_blank',rel:'noopener',text:e.id})]),\n      el('div',{class:'desc',text:e.description}),\n      el('div',{class:'meta'},[\n        el('span',{class:'score'},[el('span',{class:'track'},[el('div',{class:'fill',style:'width:'+e.score+'%'})]),el('span',{text:String(e.score)})]),\n        el('span',{text:'★ '+stars(e.stars)}), el('span',{text:e.license||'no license'})]),\n      tags, foot]));\n  });\n}\n\nfunction renderInstalled(){\n  var d = S.data, s = $('#installed'); s.textContent='';\n  var head = el('div',{class:'bar'},[el('b',{text:d.installed.length+' plugins'}),el('span',{class:'spacer'}),\n    el('button',{class:'btn ghost',text:'Update all',onclick:function(ev){ busy(ev.target,function(){\n      return api('update-all',{}).then(function(r){ toast('Checked '+r.results.length+' plugins. Restart Claude Code to apply.','good'); return load(); }); }); }})]);\n  s.appendChild(head);\n  var max = Math.max.apply(null, d.installed.map(function(r){ return r.tokens||0; }).concat([1]));\n  var list = el('div',{class:'list'});\n  d.installed.slice().sort(function(a,b){ return (b.tokens||0)-(a.tokens||0); }).forEach(function(r){\n    var sw = el('button',{class:'sw'+(r.enabled?' on':''),title:r.enabled?'Disable':'Enable',onclick:function(ev){ busy(ev.target,function(){\n      return api('plugin',{id:r.id,verb:r.enabled?'disable':'enable'}).then(function(){ toast((r.enabled?'Disabled ':'Enabled ')+r.id,'good'); return load(); }); }); }});\n    var heavy = (r.tokens||0) > 10000;\n    list.appendChild(el('div',{class:'irow'},[\n      sw,\n      el('div',{},[el('div',{class:'t',text:r.id}),el('div',{class:'s',text:'v'+r.version+' · '+r.scope})]),\n      el('div',{class:'cost'},[el('span',{text:r.tokens==null?'n/a':'~'+fmt(r.tokens)+' tok',style:heavy?'color:var(--yellow)':''}),\n        el('div',{class:'track'},[el('div',{class:'fill',style:'width:'+Math.round(((r.tokens||0)/max)*100)+'%'})])]),\n      el('div',{class:'foot'},[\n        el('button',{class:'btn ghost',text:'Update',onclick:function(ev){ busy(ev.target,function(){\n          return api('plugin',{id:r.id,verb:'update'}).then(function(j){ toast(j.out||'done','good'); }); }); }}),\n        el('button',{class:'btn danger',text:'Remove',onclick:function(ev){ if(!confirm('Uninstall '+r.id+'?')) return; busy(ev.target,function(){\n          return api('plugin',{id:r.id,verb:'uninstall'}).then(function(){ toast('Removed '+r.id,'good'); return load(); }); }); }})])]));\n  });\n  s.appendChild(list);\n}\n\nfunction showPlan(p){\n  api('profile-plan',{name:p.name}).then(function(r){\n    var box = el('div',{class:'box'},[el('h3',{text:'Apply \"'+p.name+'\"'})]);\n    if (!r.steps.length) box.appendChild(el('div',{class:'empty',text:'Already matches this profile. Nothing to do.'}));\n    r.steps.forEach(function(st){\n      box.appendChild(el('div',{class:'step'},[el('b',{class:'a-'+st.action,text:st.action}),el('span',{text:st.plugin+' - '+st.reason})]));\n    });\n    var close = function(){ m.remove(); };\n    var foot = el('div',{class:'foot',style:'margin-top:16px'},[el('button',{class:'btn ghost',text:'Cancel',onclick:close})]);\n    if (r.steps.length) foot.appendChild(el('button',{class:'btn',text:'Apply',onclick:function(ev){ busy(ev.target,function(){\n      return api('profile-apply',{name:p.name}).then(function(a){\n        var bad = a.results.filter(function(x){return !x.ok;});\n        toast(bad.length ? bad.length+' step(s) failed' : 'Profile applied. Restart Claude Code.', bad.length?'err':'good'); close(); return load(); }); }); }}));\n    box.appendChild(foot);\n    var m = el('div',{class:'modal',onclick:function(e){ if(e.target===m) close(); }},[box]);\n    document.body.appendChild(m);\n  }).catch(function(e){ toast(e.message,'err'); });\n}\n\nfunction renderProfiles(){\n  var s = $('#profiles'); s.textContent='';\n  var g = el('div',{class:'grid'});\n  S.data.profiles.forEach(function(p){\n    g.appendChild(el('div',{class:'pcard'},[\n      el('h3',{text:p.name}),el('div',{class:'desc',text:p.description}),\n      el('div',{class:'tags'},p.repos.map(function(r){ return el('span',{class:'tag',text:r}); })),\n      el('div',{class:'foot'},[el('button',{class:'btn',text:'Preview & apply',onclick:function(){ showPlan(p); }})])]));\n  });\n  var nm = el('input',{type:'search',placeholder:'Save current setup as...'});\n  s.appendChild(g);\n  s.appendChild(el('div',{class:'bar',style:'margin-top:18px'},[nm,el('button',{class:'btn ghost',text:'Save current',onclick:function(ev){\n    if(!nm.value.trim()) return; busy(ev.target,function(){ return api('profile-save',{name:nm.value.trim()}).then(function(){ toast('Saved','good'); return load(); }); }); }})]));\n}\n\n$('#tabs').addEventListener('click', function(e){\n  var t = e.target.getAttribute('data-t'); if(!t) return;\n  S.tab = t;\n  document.querySelectorAll('#tabs button').forEach(function(b){ b.classList.toggle('on', b===e.target); });\n  ['discover','installed','profiles'].forEach(function(x){ $('#'+x).hidden = x!==t; });\n  render();\n});\ndocument.querySelectorAll('.chip').forEach(function(c){ c.addEventListener('click', function(){\n  document.querySelectorAll('.chip').forEach(function(x){ x.classList.remove('on'); });\n  c.classList.add('on'); S.filter = c.getAttribute('data-f'); render(); }); });\n$('#q').addEventListener('input', function(e){ S.q = e.target.value; renderDiscover(); });\n$('#refresh').addEventListener('click', function(ev){ busy(ev.target,function(){\n  return api('refresh',{}).then(function(r){ toast('Catalog: '+r.count+' entries ('+r.source+')','good'); return load(); }); }); });\n\nsetInterval(function(){ api('ping').catch(function(){}); }, 5000);\napi('ping').catch(function(){});\nload();\n})();\n</script>\n</body>\n</html>\n";
